
/**
 * @file components/simulacrum/GossipTicker.tsx
 * @description A persistent feed of agent communications (Gossip) generated by the PCE.
 * On mobile, it condenses to a single line or collapses entirely to save space.
 */

import React, { useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { Agent, GossipLogEntry } from '../../types';
import { getAgentAvatar } from '../../utils/agent-visuals';
import { ChevronDownIcon } from '../icons/ChevronDownIcon';

interface GossipTickerProps {
    logs: GossipLogEntry[];
    agents: Record<string, Agent>;
    onFocusAgent: (agentId: string) => void;
    className?: string;
}

const GossipItem: React.FC<{ entry: GossipLogEntry; agents: Record<string, Agent>; onFocusAgent: (id: string) => void; isCompact?: boolean }> = ({ entry, agents, onFocusAgent, isCompact }) => {
    const sourceAgent = agents[entry.sourceAgentId];
    const targetAgent = entry.targetAgentId ? agents[entry.targetAgentId] : null;

    if (!sourceAgent) return null;

    return (
        <motion.li
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0 }}
            layout
            className={`group flex items-start space-x-3 p-2 rounded-lg cursor-pointer mb-1 transition-all ${isCompact ? 'bg-transparent border-0' : 'bg-black/20 hover:bg-white/5 border border-transparent hover:border-white/5'}`}
            onClick={() => onFocusAgent(sourceAgent.id)}
        >
            {!isCompact && (
                <div className="flex-shrink-0 mt-0.5 opacity-70 group-hover:opacity-100 transition-opacity">
                    <div className="w-5 h-5 rounded bg-white/5 flex items-center justify-center text-white/80 scale-90">
                        {getAgentAvatar(sourceAgent)}
                    </div>
                </div>
            )}
            
            <div className="flex-grow min-w-0 overflow-hidden">
                <div className="flex items-center space-x-2 text-[10px] font-mono leading-none mb-1">
                    <span className="text-roman-aqua font-bold truncate">{sourceAgent.name}</span>
                    {targetAgent && (
                        <>
                            <span className="text-text-tertiary">›</span>
                            <span className="text-patina-green font-bold truncate">{targetAgent.name}</span>
                        </>
                    )}
                    {!isCompact && (
                        <span className="text-[9px] text-text-tertiary ml-auto opacity-50">
                            {new Date(entry.timestamp).toLocaleTimeString([], { hour12: false, hour: '2-digit', minute:'2-digit', second: '2-digit' })}
                        </span>
                    )}
                </div>
                <p className={`text-[10px] text-vitreous-white/90 font-lexend leading-tight ${isCompact ? 'truncate' : 'break-words'}`}>
                    {entry.message}
                </p>
            </div>
        </motion.li>
    );
};

const GossipTicker: React.FC<GossipTickerProps> = ({ logs, agents, onFocusAgent, className = '' }) => {
    const bottomRef = useRef<HTMLDivElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [isCollapsed, setIsCollapsed] = useState(false);
    const [isMobile, setIsMobile] = useState(false);

    // Detect mobile layout
    useEffect(() => {
        const checkMobile = () => setIsMobile(window.innerWidth < 768);
        checkMobile();
        window.addEventListener('resize', checkMobile);
        return () => window.removeEventListener('resize', checkMobile);
    }, []);

    // Auto-scroll to bottom when new logs arrive
    useEffect(() => {
        if (bottomRef.current && !isCollapsed) {
            bottomRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [logs.length, isCollapsed]);

    // On mobile, collapse to single line by default if logs exist
    const latestLog = logs[logs.length - 1];

    if (isMobile) {
        if (!latestLog) return null;
        return (
             <div className={`w-full px-4 mb-2 pointer-events-none ${className}`}>
                <div className="bg-black/80 backdrop-blur-md border border-white/10 rounded-full px-4 py-2 shadow-lg flex items-center justify-between pointer-events-auto">
                    <div className="flex items-center gap-2 overflow-hidden">
                        <div className="w-1.5 h-1.5 bg-imperial-purple rounded-full animate-pulse" />
                        <span className="text-[10px] font-bold text-roman-aqua truncate max-w-[80px]">
                            {agents[latestLog.sourceAgentId]?.name || 'System'}
                        </span>
                        <span className="text-[10px] text-white/80 truncate">
                            {latestLog.message}
                        </span>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className={`flex flex-col transition-all duration-300 ${className} ${isCollapsed ? 'w-auto' : 'w-80'}`}>
            <div 
                className="flex items-center justify-between px-3 py-2 bg-obsidian-black/90 backdrop-blur-xl border border-glass-border rounded-t-xl shadow-lg z-10 cursor-pointer"
                onClick={() => setIsCollapsed(!isCollapsed)}
            >
                <div className="flex items-center space-x-2">
                    <div className="relative">
                        <div className="w-2 h-2 bg-imperial-purple rounded-full animate-pulse" />
                        <div className="absolute inset-0 bg-imperial-purple rounded-full animate-ping opacity-50" />
                    </div>
                    {!isCollapsed && <span className="text-[10px] font-bold text-vitreous-white uppercase tracking-widest">PCE Feed</span>}
                </div>
                {!isCollapsed && (
                    <div className="flex items-center space-x-2">
                        <span className="text-[9px] font-mono text-text-tertiary">{logs.length} events</span>
                    </div>
                )}
                <ChevronDownIcon className={`w-3 h-3 text-text-tertiary transition-transform ${isCollapsed ? 'rotate-180' : ''}`} />
            </div>

            <AnimatePresence>
                {!isCollapsed && (
                    <motion.div 
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 250, opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        ref={containerRef}
                        className="bg-panel-bg/80 backdrop-blur-xl border-x border-b border-glass-border rounded-b-xl overflow-y-auto custom-scrollbar p-2 shadow-2xl relative flex flex-col"
                    >
                        <div className="flex-grow" /> {/* Spacer to push items down initially */}
                        <ul className="flex flex-col justify-end">
                            {logs.map((log) => (
                                <GossipItem key={log.id} entry={log} agents={agents} onFocusAgent={onFocusAgent} />
                            ))}
                            <div ref={bottomRef} />
                        </ul>
                        
                        {/* Scroll fade overlay */}
                        <div className="absolute top-0 left-0 right-0 h-8 bg-gradient-to-b from-obsidian-black/80 to-transparent pointer-events-none" />
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default GossipTicker;
